package com.duozhi.outbound;

import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;

@RestController
@AdminPermission("admin:operations")
@RequestMapping("/api/v1/admin")
public class AdminOperations {
    private final Store store;private final Transactions tx;private final Contract contract;private final Audit audit;private final IntegrationTasks integrations;private final Settings settings;
    public AdminOperations(Store store,Transactions tx,Contract contract,Audit audit,IntegrationTasks integrations,Settings settings){this.store=store;this.tx=tx;this.contract=contract;this.audit=audit;this.integrations=integrations;this.settings=settings;}
    private Identity actor(HttpServletRequest request){Identity i=Identity.from(request);i.admin("admin:operations");return i;}
    @PostMapping("/tasks/{id}/retry") public Map<String,Object> retry(@PathVariable UUID id,HttpServletRequest request){Identity i=actor(request);return tx.serialized(()->{tx.platform();Map<String,Object> task=store.one("taskoutbox","sourceAdminOperations13_0",Store.queryParameters(0,i.tenant(),store.encode("taskoutbox","id",id)));if(task==null||!"dead".equals(task.get("state")))throw new ApiError(409,"dead task not found or task is not retryable");store.update("taskoutbox",i.tenant(),id,JsonSupport.map("state","pending","attempts",0,"available_at",Store.now(),"locked_at",null,"lease_token",null,"last_error",""));if(Values.set("recording_ingest","recording_delete").contains(task.get("task_type"))){Map<String,Object> asset=store.one("recordingasset","sourceAdminOperations13_1",Store.queryParameters(0,i.tenant(),Long.parseLong(task.get("aggregate_id").toString())));if(asset!=null&&asset.get("deleted_at")==null)store.update("recordingasset",i.tenant(),asset.get("id"),JsonSupport.map("state","recording_delete".equals(task.get("task_type"))?"deletion_pending":"available"));}audit.record(i,"retry","task_outbox",id,"task_type="+task.get("task_type"));return JsonSupport.map("result","queued","task_id",id,"state","pending");});}
    @GetMapping("/sms-logs") public List<Map<String,Object>> sms(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="100") int size,@RequestParam(required=false) String state,HttpServletRequest request){Identity i=actor(request);if(state!=null&&state.length()>64)throw new ApiError(422,"invalid state");List<Object> args=new ArrayList<>(Collections.singletonList(i.tenant()));String where="WHERE tenant_id=?";if(state!=null&&!state.isEmpty()){where+=" AND state=?";args.add(state);}args.add(size);args.add(Contract.page(page,size));List<Map<String,Object>> result=new ArrayList<>();for(Map<String,Object> row:store.query("smslog","searchSms",JsonSupport.map("tenantId",i.tenant(),"state",state,"limit",size,"offset",Contract.page(page,size))))result.add(contract.output("SmsLogOut",row));return result;}
    @PostMapping("/sms-logs/{id}/retry") public Map<String,Object> smsRetry(@PathVariable long id,HttpServletRequest request){Identity i=actor(request);Map<String,Object> snapshot=tx.serialized(()->{tx.platform();Map<String,Object> row=store.require("smslog",i.tenant(),id);if(!Values.set("failed","disabled").contains(row.get("state")))throw new ApiError(409,"only failed or disabled SMS can be retried");if(!Boolean.TRUE.equals(settings.get(i.tenant(),"sms").get("enabled")))throw new ApiError(409,"SMS service is disabled");return store.update("smslog",i.tenant(),id,JsonSupport.map("state","pending"));});
        Map<String,Object> response;try{response=integrations.send(i.tenant(),snapshot.get("to_phone").toString(),snapshot.get("content").toString());}catch(RuntimeException e){tx.run(()->{store.update("smslog",i.tenant(),id,JsonSupport.map("state","failed"));audit.record(i,"retry_failed","sms_log",id,"provider request failed");return null;});throw new ApiError(502,"SMS provider request failed");}
        return tx.serialized(()->{tx.platform();Map<String,Object> latest=store.require("smslog",i.tenant(),id);if(!"pending".equals(latest.get("state")))return contract.output("SmsLogOut",latest);Map<String,Object> saved=store.update("smslog",i.tenant(),id,JsonSupport.map("state",response.getOrDefault("state","sent"),"provider_message_id",response.getOrDefault("message_id",response.getOrDefault("provider_message_id",snapshot.get("provider_message_id"))),"provider_error",null,"sent_at",Store.now()));audit.record(i,"retry","sms_log",id,"state="+saved.get("state"));return contract.output("SmsLogOut",saved);});
    }
    @GetMapping("/audit-logs") public List<Map<String,Object>> audits(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="100") int size,HttpServletRequest request){List<Map<String,Object>> result=new ArrayList<>();for(Map<String,Object> row:store.query("auditlog","sourceAdminOperations19_3",Store.queryParameters(0,actor(request).tenant(),size,Contract.page(page,size))))result.add(contract.output("AuditLogOut",row));return result;}
}
